void Solver::bump_var(int var, double coeff) {
    // Increment activity for the variable
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Global rescaling when any activity becomes too large
    const double THRESH = 1e90;
    const double SCALE  = 1e-90;
    if (activity[var] > THRESH || var_inc > THRESH) {
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // Keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
